 async function interact(){
  if(me.room){const a=I.activity(me);if(a?.kind==='exit')await action({type:'exitBuilding'});else if(a?.kind==='activity')panel(a.panel);else toast('Explore the room. The activity terminal is at the back; the exit is at the bottom.');return;}
  const building=I.nearest(me);if(building){manualAim=false;await action({type:'enterBuilding',building:building.roomId});return;}
  const guide=R.nearest(me);if(guide){toast(guide.line);panel(guide.panel);return;}
  if(me.contract?.type==='courier'&&Math.hypot(me.x-WORLD.route[1].x,me.y-WORLD.route[1].y)<100){await action({type:'deliver'});return;}
  const checkpoint=WORLD.route[me.route];if(checkpoint&&Math.hypot(me.x-checkpoint.x,me.y-checkpoint.y)<110){await action({type:'checkpoint'});if(tracked?.id==='route')tracked=null;return;}
  const station=C.nearest(me);if(station){if(station.kind==='directions'){markDistrict(station.district);return;}if(station.kind==='roadmap'){panel('mobility');return;}panel(station.kind==='mission'?'missions':station.kind);return;}
  if(me.area==='fortress'){panel('build');return;}toast('Approach an activity marker, or open Map for walking directions.');
 }

